import json, os, sys
from coverage import Coverage
cov = Coverage(data_file=sys.argv[1])
cov.load()
data = cov.get_data()
focus = set(json.loads(sys.argv[2])) if len(sys.argv) > 2 else set()
files = {}
lines = {}
for fname in data.measured_files():
    by_line = data.contexts_by_lineno(fname)
    tids = set()
    for names in by_line.values():
        for raw in names:
            tid = raw.split('|')[0]
            if tid:
                tids.add(tid)
    if not tids:
        continue
    files[fname] = sorted(tids)
    try:
        rel = os.path.relpath(fname).replace(os.sep, '/')
    except ValueError:
        continue
    if rel not in focus:
        continue
    per_line = {}
    for lineno, names in by_line.items():
        ltids = set()
        for raw in names:
            tid = raw.split('|')[0]
            if tid:
                ltids.add(tid)
        if ltids:
            per_line[str(lineno)] = sorted(ltids)
    if per_line:
        lines[fname] = per_line
print(json.dumps({'files': files, 'lines': lines}))

